/*
 * TerraZ hero compatibility fixes.
 * The legacy mgGlitch plugin was no longer used; this loaded slot now keeps
 * the secondary connection links synchronized with the copy button and
 * replaces opaque social PNGs with vector/font icons.
 */
(function (window, document) {
  "use strict";

  function addStyles() {
    if (document.getElementById("hero-compatibility-fixes")) {
      return;
    }

    var style = document.createElement("style");
    style.id = "hero-compatibility-fixes";
    style.textContent = [
      ".hero-1 .front-content.page-enter-animated .server-actions-block{transform:translateY(100%)!important;opacity:0!important}",
      ".hero-1 .front-content.page-enter-animated.show .server-actions-block{transition:1s 1s;transform:translateY(0)!important;opacity:1!important}",
      ".hero-1 .front-content.page-enter-animated .server-actions-block .server-address-row{transform:none!important;opacity:1!important;transition:none!important}",
      ".hero-1 .front-content .server-actions-block .hero-secondary-links{margin-bottom:24px}",
      ".hero-1 .front-content .social-links-row .social-link::before{content:none!important;display:none!important}",
      ".hero-1 .front-content .social-links-row .social-icon{display:block;font-size:19px;line-height:1;color:currentColor;opacity:.94;transform:scale(1);transition:opacity .22s ease,transform .22s ease}",
      ".hero-1 .front-content .social-links-row .social-icon-discord{width:20px;height:20px;fill:currentColor}",
      ".hero-1 .front-content .social-links-row .social-link:hover .social-icon,.hero-1 .front-content .social-links-row .social-link:focus-visible .social-icon{opacity:1;transform:scale(1.08)}",
      "@media only screen and (max-width:520px),only screen and (max-height:560px){.hero-1 .front-content .social-links-row .social-icon{font-size:17px}.hero-1 .front-content .social-links-row .social-icon-discord{width:18px;height:18px}}",
      "@media only screen and (max-height:480px){.hero-1 .front-content .server-actions-block .hero-secondary-links{margin-bottom:12px}}",
      "@media (prefers-reduced-motion:reduce){.hero-1 .front-content.page-enter-animated .server-actions-block,.hero-1 .front-content.page-enter-animated.show .server-actions-block{transition:none!important;transform:none!important;opacity:1!important}}"
    ].join("");
    document.head.appendChild(style);
  }

  function groupServerActions() {
    var addressRow = document.querySelector(".server-address-row");
    var secondaryLinks = document.querySelector(".hero-secondary-links");

    if (!addressRow || !secondaryLinks || (addressRow.parentNode === secondaryLinks.parentNode && addressRow.parentNode.classList.contains("server-actions-block"))) {
      return;
    }

    var wrapper = document.createElement("div");
    wrapper.className = "server-actions-block";
    addressRow.parentNode.insertBefore(wrapper, addressRow);
    wrapper.appendChild(addressRow);
    wrapper.appendChild(secondaryLinks);
  }

  function discordIcon() {
    return '<svg class="social-icon social-icon-discord" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' +
      '<path d="M7 7.6c1.5-.7 3.2-1.1 5-1.1s3.5.4 5 1.1c1.1 1.7 1.8 3.7 2 5.8-.9 1.2-2 2.2-3.3 2.9l-.8-1.1c.8-.4 1.5-.8 2.1-1.3-1.6.8-3.3 1.2-5 1.2s-3.4-.4-5-1.2c.6.5 1.3.9 2.1 1.3l-.8 1.1C7 15.6 5.9 14.6 5 13.4c.2-2.1.9-4.1 2-5.8zm2.2 3.1c-.6 0-1.1.6-1.1 1.3s.5 1.3 1.1 1.3 1.1-.6 1.1-1.3-.5-1.3-1.1-1.3zm5.6 0c-.6 0-1.1.6-1.1 1.3s.5 1.3 1.1 1.3 1.1-.6 1.1-1.3-.5-1.3-1.1-1.3z"/>' +
      "</svg>";
  }

  function replaceSocialIcons() {
    var icons = [
      ['a.social-link[href*="vk.com"]', '<i class="fa fa-vk social-icon" aria-hidden="true"></i>'],
      ['a.social-link[href*="youtube.com"]', '<i class="fa fa-youtube-play social-icon" aria-hidden="true"></i>'],
      ['a.social-link[href="/conference"]', discordIcon()],
      ['a.social-link[href*="t.me"]', '<i class="fa fa-paper-plane social-icon" aria-hidden="true"></i>'],
      ['a.social-link[href*="twitch.tv"]', '<i class="fa fa-twitch social-icon" aria-hidden="true"></i>']
    ];

    icons.forEach(function (item) {
      var link = document.querySelector(item[0]);
      if (link) {
        link.innerHTML = item[1];
      }
    });
  }

  function applyFixes() {
    groupServerActions();
    replaceSocialIcons();
  }

  addStyles();

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      window.setTimeout(applyFixes, 0);
    });
  } else {
    window.setTimeout(applyFixes, 0);
  }
}(window, document));
